    # PCFForceModelT
    def Pack(self, builder):
        if self.THIRD_BODY_IDS is not None:
            if np is not None and type(self.THIRD_BODY_IDS) is np.ndarray:
                THIRD_BODY_IDS = builder.CreateNumpyVector(self.THIRD_BODY_IDS)
            else:
                PCFForceModelStartTHIRD_BODY_IDSVector(builder, len(self.THIRD_BODY_IDS))
                for i in reversed(range(len(self.THIRD_BODY_IDS))):
                    builder.PrependInt32(self.THIRD_BODY_IDS[i])
                THIRD_BODY_IDS = builder.EndVector()
        if self.WEATHER is not None:
            WEATHER = self.WEATHER.Pack(builder)
        if self.EPHEMERIS_SOURCE is not None:
            EPHEMERIS_SOURCE = builder.CreateString(self.EPHEMERIS_SOURCE)
        if self.ECOM2 is not None:
            ECOM2 = self.ECOM2.Pack(builder)
        if self.EMPIRICAL_TERMS is not None:
            EMPIRICAL_TERMS = self.EMPIRICAL_TERMS.Pack(builder)
        PCFForceModelStart(builder)
        PCFForceModelAddGRAVITY_CHOICE(builder, self.GRAVITY_CHOICE)
        PCFForceModelAddENABLE_POINT_MASS(builder, self.ENABLE_POINT_MASS)
        PCFForceModelAddGRAVITATIONAL_PARAMETER(builder, self.GRAVITATIONAL_PARAMETER)
        PCFForceModelAddENABLE_J2(builder, self.ENABLE_J2)
        PCFForceModelAddENABLE_J3(builder, self.ENABLE_J3)
