        PCFForceModelAddENABLE_HIGHER_ZONALS(builder, self.ENABLE_HIGHER_ZONALS)
        PCFForceModelAddMAXIMUM_DEGREE(builder, self.MAXIMUM_DEGREE)
        PCFForceModelAddHAS_MAXIMUM_DEGREE(builder, self.HAS_MAXIMUM_DEGREE)
        PCFForceModelAddMAXIMUM_ORDER(builder, self.MAXIMUM_ORDER)
        PCFForceModelAddHAS_MAXIMUM_ORDER(builder, self.HAS_MAXIMUM_ORDER)
        PCFForceModelAddENABLE_THIRD_BODY(builder, self.ENABLE_THIRD_BODY)
        if self.THIRD_BODY_IDS is not None:
            PCFForceModelAddTHIRD_BODY_IDS(builder, THIRD_BODY_IDS)
        PCFForceModelAddENABLE_SRP(builder, self.ENABLE_SRP)
        PCFForceModelAddENABLE_DRAG(builder, self.ENABLE_DRAG)
        PCFForceModelAddINITIAL_MASS_KG(builder, self.INITIAL_MASS_KG)
        PCFForceModelAddAREA_M2(builder, self.AREA_M2)
        PCFForceModelAddREFLECTIVITY_COEFFICIENT(builder, self.REFLECTIVITY_COEFFICIENT)
        PCFForceModelAddDRAG_COEFFICIENT(builder, self.DRAG_COEFFICIENT)
        PCFForceModelAddATMOSPHERE_MODEL(builder, self.ATMOSPHERE_MODEL)
        if self.WEATHER is not None:
            PCFForceModelAddWEATHER(builder, WEATHER)
        if self.EPHEMERIS_SOURCE is not None:
            PCFForceModelAddEPHEMERIS_SOURCE(builder, EPHEMERIS_SOURCE)
        PCFForceModelAddSOLID_TIDES(builder, self.SOLID_TIDES)
        PCFForceModelAddRELATIVITY(builder, self.RELATIVITY)
        PCFForceModelAddIN_TRACK_ACCELERATION_M_S2(builder, self.IN_TRACK_ACCELERATION_M_S2)
        PCFForceModelAddHAS_IN_TRACK_ACCELERATION_M_S2(builder, self.HAS_IN_TRACK_ACCELERATION_M_S2)
        PCFForceModelAddDRAG_AREA_OVER_MASS_RATE_M2_KG_S(builder, self.DRAG_AREA_OVER_MASS_RATE_M2_KG_S)
        PCFForceModelAddHAS_DRAG_AREA_OVER_MASS_RATE_M2_KG_S(builder, self.HAS_DRAG_AREA_OVER_MASS_RATE_M2_KG_S)
        PCFForceModelAddMAXIMUM_TESSERAL_DEGREE(builder, self.MAXIMUM_TESSERAL_DEGREE)
        PCFForceModelAddHAS_MAXIMUM_TESSERAL_DEGREE(builder, self.HAS_MAXIMUM_TESSERAL_DEGREE)
        PCFForceModelAddRADIATION_PRESSURE_MODEL(builder, self.RADIATION_PRESSURE_MODEL)
        PCFForceModelAddGNSS_BLOCK(builder, self.GNSS_BLOCK)
        if self.ECOM2 is not None:
            PCFForceModelAddECOM2(builder, ECOM2)
        PCFForceModelAddEARTH_RADIATION(builder, self.EARTH_RADIATION)
        PCFForceModelAddEARTH_RADIATION_RESOLUTION_DEG(builder, self.EARTH_RADIATION_RESOLUTION_DEG)
        PCFForceModelAddEARTH_RADIATION_AREA_OVER_MASS_M2_KG(builder, self.EARTH_RADIATION_AREA_OVER_MASS_M2_KG)
        PCFForceModelAddHAS_EARTH_RADIATION_AREA_OVER_MASS_M2_KG(builder, self.HAS_EARTH_RADIATION_AREA_OVER_MASS_M2_KG)
        PCFForceModelAddOCEAN_TIDES(builder, self.OCEAN_TIDES)
        PCFForceModelAddOCEAN_TIDE_MAXIMUM_DEGREE(builder, self.OCEAN_TIDE_MAXIMUM_DEGREE)
        PCFForceModelAddOCEAN_TIDE_MAXIMUM_ORDER(builder, self.OCEAN_TIDE_MAXIMUM_ORDER)
        PCFForceModelAddCENTRAL_BODY_NAIF_ID(builder, self.CENTRAL_BODY_NAIF_ID)
        PCFForceModelAddEPHEMERIS_KIND(builder, self.EPHEMERIS_KIND)
